DELIMITER $$
--
-- Procedimentos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `AjustarVinculosEventos` ()   BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_id_evento INT;
    DECLARE v_novo_id_end INT;
    DECLARE v_novo_id_cont INT;
    
    DECLARE cur CURSOR FOR SELECT id_evento FROM eventos ORDER BY id_evento ASC;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_id_evento;
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- Criar endereço (iniciando em 241+)
        VALUES ('A definir', 'A definir', 'SP', 'Brasil');
        SET v_novo_id_end = LAST_INSERT_ID();

        -- Criar contato (iniciando em 241+)
        SET v_novo_id_cont = LAST_INSERT_ID();

        -- Atualizar o evento
        UPDATE eventos 
        SET id_endereco = v_novo_id_end, 
            id_contato = v_novo_id_cont 
        WHERE id_evento = v_id_evento;
        
    END LOOP;

    CLOSE cur;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `recalcular_ranking` (IN `p_modalidade` INT, IN `p_categoria` INT)   BEGIN
    SET @pos = 0;
    UPDATE ranking
    SET posicao = (@pos := @pos + 1)
    WHERE id_modalidade = p_modalidade
    AND id_categoria_peso = p_categoria
    ORDER BY pontos DESC;
END$$

DELIMITER ;

