DELIMITER $$
CREATE TRIGGER `atualizar_estatisticas_luta` AFTER INSERT ON `historico_lutas` FOR EACH ROW BEGIN

DECLARE v_modalidade INT;
DECLARE v_categoria INT;
DECLARE v_metodo VARCHAR(100);

-- buscar dados da luta
SELECT id_modalidade, id_categoria_peso, metodo_vitoria
INTO v_modalidade, v_categoria, v_metodo
FROM lutas
WHERE id_luta = NEW.id_luta;

-- ------------------------------------------------
-- ATUALIZA CARTEL DO ATLETA
-- ------------------------------------------------

IF NEW.resultado = 'vitoria' THEN

    UPDATE cartel_atleta
    SET vitorias = vitorias + 1
    WHERE id_atleta = NEW.id_atleta;

    UPDATE ranking
    SET 
        vitorias = vitorias + 1,
        pontos = pontos + 10
    WHERE id_atleta = NEW.id_atleta;

END IF;

IF NEW.resultado = 'derrota' THEN

    UPDATE cartel_atleta
    SET derrotas = derrotas + 1
    WHERE id_atleta = NEW.id_atleta;

    UPDATE ranking
    SET derrotas = derrotas + 1
    WHERE id_atleta = NEW.id_atleta;

END IF;

IF NEW.resultado = 'empate' THEN

    UPDATE cartel_atleta
    SET empates = empates + 1
    WHERE id_atleta = NEW.id_atleta;

    UPDATE ranking
    SET 
        empates = empates + 1,
        pontos = pontos + 2
    WHERE id_atleta = NEW.id_atleta;

END IF;

-- ------------------------------------------------
-- METODO DA VITORIA
-- ------------------------------------------------

IF v_metodo LIKE '%nocaute%' THEN
    UPDATE cartel_atleta
    SET nocautes = nocautes + 1
    WHERE id_atleta = NEW.id_atleta;
END IF;

IF v_metodo LIKE '%finalizacao%' THEN
    UPDATE cartel_atleta
    SET finalizacoes = finalizacoes + 1
    WHERE id_atleta = NEW.id_atleta;
END IF;

IF v_metodo LIKE '%decisao%' THEN
    UPDATE cartel_atleta
    SET decisoes = decisoes + 1
    WHERE id_atleta = NEW.id_atleta;
END IF;

-- ------------------------------------------------
-- ATUALIZA DATA ULTIMA LUTA
-- ------------------------------------------------

UPDATE ranking
SET ultima_luta = CURRENT_DATE
WHERE id_atleta = NEW.id_atleta;

-- ------------------------------------------------
-- RECALCULA POSIÇÃO DO RANKING
-- ------------------------------------------------

CALL recalcular_ranking(v_modalidade, v_categoria);

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `atualizar_ranking_automatico` AFTER INSERT ON `historico_lutas` FOR EACH ROW BEGIN

DECLARE v_modalidade INT;
DECLARE v_categoria INT;

SELECT id_modalidade, id_categoria_peso
INTO v_modalidade, v_categoria
FROM lutas
WHERE id_luta = NEW.id_luta;

CALL recalcular_ranking(v_modalidade, v_categoria);

END
$$
DELIMITER ;

